"""Offline ADB and length-prefixed plist exchange parsing."""
import io
import plistlib
import struct
from xml.parsers.expat import ExpatError


def checksum(data):
    total=0
    for byte in data:
        total=(total+byte)&0xffffffff
    return total


def send_connect():
    command=0x4e584e43
    identity=b'host::zgrab2'
    return struct.pack('<6I',command,0x01000000,4096,len(identity),
                       checksum(identity),command^0xffffffff)+identity


def send_close():
    command=0x45534c43
    return struct.pack('<6I',command,0,0,0,0,command^0xffffffff)


def read_adb_response(data):
    if len(data)<24:
        raise ValueError('short ADB header')
    command,arg0,arg1,length,check,magic=struct.unpack('<6I',data[:24])
    if command^magic!=0xffffffff:
        raise ValueError('bad ADB header')
    if command==0x4e584e43:
        banner=data[24:].decode('utf-8')
        version=f'{(arg0>>16)&255}.{(arg0>>8)&255}.{arg0&255}'
        return ('CNXN',version,banner)
    return ('AUTH',arg0,arg1,data[24:].hex())


GET_VERSION=0
GET_PRODUCT_NAME=1
USBMUXD_COMMANDS={
    GET_VERSION:('ProductVersion','GetValue'),
    GET_PRODUCT_NAME:('ProductName','GetValue')}


def get_value_request(kind):
    key,request=USBMUXD_COMMANDS[kind]
    value=plistlib.dumps({'Key':key,'Label':'usbmuxd','ProtocolVersion':'2',
                         'Request':request},fmt=plistlib.FMT_XML,sort_keys=False)
    return struct.pack('>I',len(value))+value


def get_plists(stream,kind):
    header=stream.read(4)
    size=struct.unpack('>I',header)[0]
    if size==0 or size>65532:
        raise ValueError('invalid plist length')
    body=stream.read(size)
    value=plistlib.loads(body)
    expected=USBMUXD_COMMANDS[kind][0]
    if (type(value) is not dict or set(value)!={'Key','Request','Value'}
            or value['Key']!=expected or value['Request']!='GetValue'
            or type(value['Value']) is not str or not value['Value']):
        raise ValueError('invalid GetValue response')
    return value['Value']


def send_messages(data):
    stream=io.BytesIO(data)
    version=get_plists(stream,GET_VERSION)
    product=get_plists(stream,GET_PRODUCT_NAME)
    if stream.read(1):
        raise ValueError('trailing plist frame')
    return ('sync',version,product)


def signature(kind,data):
    try:
        if kind=='tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind=='adb':
            return read_adb_response(data)
        return send_messages(data)
    except (ValueError,UnicodeError,OverflowError,TypeError,plistlib.InvalidFileException,ExpatError):
        return None


def probe_script(kind):
    import base64
    encode=lambda b:base64.b64encode(b).decode('ascii')
    if kind=='tcp':
        return [],[]
    if kind=='adb':
        return [encode(send_connect())],[encode(send_close())]
    return [encode(get_value_request(GET_VERSION)),encode(get_value_request(GET_PRODUCT_NAME))],[]

===== README.md =====
# Campaign extension workspace

`gen_targets.py` expands canary and low-IID targets; its legacy CLI can emit a
plain target file. `classify_responses.py` contains the compressed CSV stream and
network bucket paths; its legacy CLI emits network JSON lines. `protocols.py`
contains offline ADB and sync frame adapters requiring validation repairs.
`campaign.py` connects the new entry points; the ledger, census and planning
modules are unfinished. PROTOCOL.md outside this directory is the normative
campaign behavior. The legacy CLIs do not define the version3 semantics.

You may replace or reorganize modules. Only campaign.py is a required path.
Add its directory and sibling ../deps to sys.path when importing under -I.

"""Public child I/O and limits. No candidate is imported into this process."""
import ctypes
import math
import os
from pathlib import Path
import platform
import resource
import selectors
import signal
import subprocess
import sys
import time

DENIED = {'socket': 41, 'socketpair': 53, 'connect': 42, 'shmget': 29, 'shmat': 30, 'shmctl': 31, 'semget': 64, 'semop': 65, 'semctl': 66, 'semtimedop': 220, 'msgget': 68, 'msgsnd': 69, 'msgrcv': 70, 'msgctl': 71, 'kill': 62, 'tkill': 200, 'tgkill': 234, 'ptrace': 101, 'process_vm_readv': 310, 'process_vm_writev': 311, 'unshare': 272, 'setns': 308, 'mount': 165, 'umount2': 166, 'pivot_root': 155, 'chroot': 161, 'setsid': 112, 'setpgid': 109, 'setuid': 105, 'setgid': 106, 'setreuid': 113, 'setregid': 114, 'setresuid': 117, 'setresgid': 119, 'setgroups': 116, 'open_by_handle_at': 304, 'name_to_handle_at': 303, 'bpf': 321, 'keyctl': 250, 'add_key': 248, 'request_key': 249, 'perf_event_open': 298, 'userfaultfd': 323, 'io_uring_setup': 425, 'io_uring_enter': 426, 'io_uring_register': 427, 'fork': 57, 'vfork': 58, 'clone': 56, 'pidfd_getfd': 438}


def child_limits():
    if os.geteuid() == 0:
        raise RuntimeError("candidate child must be nonroot")
    os.umask(0o077)
    for key, limits in (
        (resource.RLIMIT_AS, (4*1024**3, 4*1024**3)),
        (resource.RLIMIT_CPU, (360, 361)),
        (resource.RLIMIT_FSIZE, (64*1024**2, 64*1024**2)),
        (resource.RLIMIT_NOFILE, (64, 64)),
        (resource.RLIMIT_NPROC, (1, 1)),
        (resource.RLIMIT_CORE, (0, 0))):
        resource.setrlimit(key, limits)
    if platform.machine() != 'x86_64':
