"""Revision-aware lease census and causal application service classification."""
from common import addresses
from ledger import group_records, reconcile
from protocols import signature


def _empty_service(service_id):
    return {'id': service_id,
            'internal_open': [], 'internal_closed': [],
            'external_open': [], 'external_closed': [],
            'internal_only': [], 'protocol_errors': 0}


def _status_for_group(group_rows, kind):
    """Return ('open', sig) / ('closed', None) / ('unknown', None), errors."""
    max_attempt = -1
    for _, record in group_rows:
        if record.attempt > max_attempt:
            max_attempt = record.attempt
    all_closed = True
    all_open = True
    signatures = []
    errors = 0
    for _, record in group_rows:
        if record.attempt != max_attempt:
            continue
        if record.result == 'closed':
            all_open = False
        elif record.result == 'timeout':
            all_closed = False
            all_open = False
        elif record.result == 'open':
            all_closed = False
            sig = signature(kind, record.payload)
            if sig is None:
                all_open = False
                errors += 1
            else:
                signatures.append(sig)
        else:
            # Should be impossible after record validation.
            all_closed = False
            all_open = False
    if all_closed:
        return 'closed', None, errors
    if all_open and signatures and all(sig == signatures[0] for sig in signatures):
        return 'open', signatures[0], errors
    return 'unknown', None, errors


def build(context, records, low):
    """Build all query snapshots and the frozen request-activity map."""
    groups = group_records(records)
    lease_ids = sorted(context['leases'])
    service_ids = sorted(context['services'])
    services_kind = context['services']
    leases = context['leases']

    # Per-query (internal address set, {service: (open set, closed set)}).
    info_by_query = {}
    snapshots = []

    for query in context['queries']:
        (live, deleted, conflict), live_icmp, live_app = reconcile(groups, query)

        icmp_by_lease = {lid: [] for lid in lease_ids}
        app_by_lease = {lid: [] for lid in lease_ids}
        for record in live_icmp:
            icmp_by_lease[record.lease].append(record)
        for record in live_app:
            app_by_lease[record.lease].append(record)

        unbound_total = 0
        lease_outputs = []
        query_info = {}

        for lease_id in lease_ids:
            lease = leases[lease_id]
            is_active = lease['start'] <= query < lease['end']

            internal = set()
            external = set()
            internal_witness = {}
            external_witness = {}
            conflicts = []

            if not is_active:
                state = 'inactive'
                unresolved = []
            else:
                alias = False
                for record in icmp_by_lease[lease_id]:
                    target = record.target
                    responder = record.responder
                    result = record.result
                    if record.canary:
                        if result == 'echo' and responder == target:
                            alias = True
                        # Other canary responses establish neither role.
                        continue
                    if result == 'echo' and responder == target:
                        previous = internal_witness.get(target)
                        if previous is None or record.event < previous:
                            internal_witness[target] = record.event
                    elif result != 'timeout' and responder != target:
                        previous = external_witness.get(responder)
                        if previous is None or record.event < previous:
                            external_witness[responder] = record.event
                    # A timeout, or a self error, establishes no role.

                internal = set(internal_witness)
                external = set(external_witness)
                conflicts = sorted(internal & external)
                if alias:
                    state = 'alias'
                elif conflicts:
                    state = 'conflict'
                else:
                    state = 'usable'

            if state == 'usable':
                unresolved = sorted(low[lease_id] - internal - external)
            elif state == 'inactive':
                unresolved = []
            else:
                unresolved = sorted(low[lease_id])
                internal = set()
                external = set()
                internal_witness = {}
                external_witness = {}

            # ---- application census -------------------------------------
            service_outputs = []
            if state != 'usable':
                unbound_total += len(app_by_lease[lease_id])
                for service_id in service_ids:
                    service_outputs.append(_empty_service(service_id))
                query_info[lease_id] = (set(), {})
            else:
                eligible = {}
                for record in app_by_lease[lease_id]:
                    target = record.target
                    if target in internal:
                        role = 1
                        witness = internal_witness.get(target)
                    elif target in external:
                        role = 2
                        witness = external_witness.get(target)
                    else:
                        unbound_total += 1
                        continue
                    if witness is None or witness > record.event:
                        unbound_total += 1
                        continue
                    by_target = eligible.get(record.service)
                    if by_target is None:
                        by_target = {}
                        eligible[record.service] = by_target
                    group_rows = by_target.get(target)
                    if group_rows is None:
                        by_target[target] = [(role, record)]
                    else:
                        group_rows.append((role, record))

                status_map = {}
                for service_id in service_ids:
                    groups_for_service = eligible.get(service_id)
                    internal_open = set()
                    internal_closed = set()
                    external_open = set()
                    external_closed = set()
                    protocol_errors = 0
                    if groups_for_service:
                        kind = services_kind[service_id]
                        for target, group_rows in groups_for_service.items():
                            status, _sig, errors = _status_for_group(group_rows, kind)
                            protocol_errors += errors
                            role = group_rows[0][0]
                            if status == 'open':
                                if role == 1:
                                    internal_open.add(target)
                                else:
                                    external_open.add(target)
                            elif status == 'closed':
                                if role == 1:
                                    internal_closed.add(target)
                                else:
                                    external_closed.add(target)
                    status_map[service_id] = (internal_open, internal_closed)
                    if external and external_closed == external:
                        internal_only = internal_open
                    else:
                        internal_only = set()
                    service_outputs.append({
                        'id': service_id,
                        'internal_open': addresses(internal_open),
                        'internal_closed': addresses(internal_closed),
                        'external_open': addresses(external_open),
                        'external_closed': addresses(external_closed),
                        'internal_only': addresses(internal_only),
                        'protocol_errors': protocol_errors,
                    })
                query_info[lease_id] = (internal, status_map)

            lease_outputs.append({
                'lease': lease_id,
                'state': state,
                'conflicts': addresses(conflicts),
                'internal': addresses(internal),
                'external': addresses(external),
                'unresolved': addresses(unresolved),
                'services': service_outputs,
            })

        info_by_query[query] = query_info
        snapshots.append({
            'at': query,
            'ledger': {'live': live, 'deleted': deleted, 'conflict': conflict},
            'unbound_applications': unbound_total,
            'leases': lease_outputs,
        })

    # Request activity is frozen at the request's own query.
    active_map = {}
    for request_id in sorted(context['requests']):
        request = context['requests'][request_id]
        query_info = info_by_query[request['at']]
        internal, status_map = query_info.get(request['lease'], (set(), {}))
        target = request['address']
        is_active = False
        if target in internal:
            open_set, closed_set = status_map.get(request['service'], (set(), set()))
            is_active = target not in open_set and target not in closed_set
        active_map[request_id] = is_active

    return snapshots, active_map

"""Optimal quota-constrained follow-up planning and probe certificates."""
from protocols import probe_script


def _empty_plan():
    return {'resolved': 0, 'cost': 0, 'assignments': []}


def solve(context, active):
    requests = context['requests']
    offers = context['offers']
    leases = context['leases']
    if not requests or not offers:
        return _empty_plan()

    # Collect the listed request/offer pairs that satisfy every static
    # assignment precondition.  Activity itself was frozen earlier.
    cross = []
    used_offers = set()
    for offer_id, offer in offers.items():
        capacity = offer['capacity']
        if capacity <= 0:
            continue
        service = offer['service']
        network = offer['network']
        first = int(network.network_address)
        last = int(network.broadcast_address)
        offer_time = offer['time']
        listed = []
        for request_id in offer['requests']:
            if not active.get(request_id):
                continue
            request = requests[request_id]
            if request['service'] != service:
                continue
            if request['at'] > offer_time:
                continue
            if offer_time >= leases[request['lease']]['end']:
                continue
            if first <= request['address'] <= last:
                listed.append(request_id)
        if listed:
            used_offers.add(offer_id)
            for request_id in listed:
                cross.append((request_id, offer_id))
    if not cross:
        return _empty_plan()

    import networkx as nx

    request_ids = sorted({request_id for request_id, _ in cross})
    offer_ids = sorted(used_offers)

    next_node = 1
    source = 0
    request_quota_node = {}
    for node_id in context['request_quotas']:
        request_quota_node[node_id] = next_node
        next_node += 1
    request_node = {}
    for request_id in request_ids:
        request_node[request_id] = next_node
        next_node += 1
    offer_node = {}
    for offer_id in offer_ids:
        offer_node[offer_id] = next_node
        next_node += 1
    offer_quota_node = {}
    for node_id in context['offer_quotas']:
        offer_quota_node[node_id] = next_node
        next_node += 1
    sink = next_node
    next_node += 1

    graph = nx.DiGraph()
    graph.add_nodes_from(range(next_node))

    # Request forest: source -> root, parent -> child, capacity on the arc
    # entering a node equals that node's subtree capacity.
    for node_id, node in context['request_quotas'].items():
        capacity = node['capacity']
        if capacity <= 0:
            continue
        parent = node['parent']
        upper = source if parent is None else request_quota_node[parent]
        graph.add_edge(upper, request_quota_node[node_id],
                       capacity=capacity, weight=0)

    # Attach each relevant request to its request-quota group.
    for request_id in request_ids:
        request = requests[request_id]
        graph.add_edge(request_quota_node[request['group']],
                       request_node[request_id], capacity=1, weight=0)

    # Assignment arcs.  Each carries the offer's per-assignment cost.
    for request_id, offer_id in cross:
        graph.add_edge(request_node[request_id], offer_node[offer_id],
                       capacity=1, weight=offers[offer_id]['cost'])

    # Per-offer capacity then the offer forest, flowing toward the sink.
    for offer_id in offer_ids:
        offer = offers[offer_id]
        graph.add_edge(offer_node[offer_id],
                       offer_quota_node[offer['group']],
                       capacity=offer['capacity'], weight=0)
    for node_id, node in context['offer_quotas'].items():
        capacity = node['capacity']
        if capacity <= 0:
            continue
        parent = node['parent']
        lower = sink if parent is None else offer_quota_node[parent]
        graph.add_edge(offer_quota_node[node_id], lower,
                       capacity=capacity, weight=0)

    # Maximum cardinality is just the maximum flow value of this network.
    max_count = nx.maximum_flow_value(graph, source, sink)
    if max_count <= 0:
        return _empty_plan()

    # Keep only nodes that lie on some source-sink path.  Other nodes cannot
    # carry flow in any feasible maximum-cardinality flow.
    def reachable(start, reverse):
        seen = {start}
        stack = [start]
        if reverse:
            while stack:
                node = stack.pop()
                for previous in graph.predecessors(node):
                    if previous not in seen:
                        edge = graph.get_edge_data(previous, node)
                        if edge and edge.get('capacity', 0) > 0:
                            seen.add(previous)
                            stack.append(previous)
        else:
            while stack:
                node = stack.pop()
                for following in graph.successors(node):
                    if following not in seen:
                        edge = graph.get_edge_data(node, following)
                        if edge and edge.get('capacity', 0) > 0:
                            seen.add(following)
                            stack.append(following)
        return seen

    from_source = reachable(source, False)
    to_sink = reachable(sink, True)
    keep = from_source & to_sink
    if len(keep) != next_node:
        graph.remove_nodes_from([node for node in graph if node not in keep])

    graph.nodes[source]['demand'] = -max_count
    graph.nodes[sink]['demand'] = max_count
    _cost, flow = nx.network_simplex(graph)

    script_cache = {}
    assignments = []
    total_cost = 0
    for request_id, offer_id in cross:
        request_flow = flow.get(request_node[request_id])
        if not request_flow:
            continue
        if request_flow.get(offer_node[offer_id], 0) <= 0:
            continue
        offer = offers[offer_id]
        total_cost += offer['cost']
        request = requests[request_id]
        kind = context['services'][request['service']]
        script = script_cache.get(kind)
        if script is None:
            script = probe_script(kind)
            script_cache[kind] = script
        assignments.append({'request': request_id, 'offer': offer_id,
                            'send': list(script[0]),
                            'finish': list(script[1])})

    assignments.sort(key=lambda item: item['request'])
    return {'resolved': len(assignments), 'cost': total_cost,
            'assignments': assignments}

#!/usr/bin/env python3
"""Bounded CSV/Zstandard capture decoding for the offline campaign."""
import base64
import binascii
import csv
import io

import zstandard as zstd

from common import (COLUMNS, MAX_DECODED, MAX_DECOMPRESSED, MAX_FIELD_BYTES,
                    MAX_RECORDS, MAX_WINDOW, CaptureError)
from ledger import parse_record


def _complete_frames(data):
    """Validate complete dictionary-free Zstandard framing."""
    at = 0
    size = len(data)
    while at < size:
        if at + 4 > size:
            raise CaptureError('truncated Zstandard magic')
        magic = int.from_bytes(data[at:at + 4], 'little')
        if 0x184d2a50 <= magic <= 0x184d2a5f:
            if at + 8 > size:
                raise CaptureError('truncated skippable frame')
            frame_size = int.from_bytes(data[at + 4:at + 8], 'little')
            at += 8 + frame_size
            if at > size:
                raise CaptureError('truncated skippable frame')
            continue
        if magic != 0xfd2fb528 or at + 5 > size:
            raise CaptureError('invalid Zstandard frame magic')

        flag = data[at + 4]
        # Bit 3 is reserved; bit 4 is an unused header bit and is ignored.
        if flag & 0x08:
            raise CaptureError('reserved Zstandard frame bit')
        single = bool(flag & 0x20)
        dictionary_len = (0, 1, 2, 4)[flag & 0x03]
        content_size_len = (1 if single else 0, 2, 4, 8)[flag >> 6]
        header_len = 5 + (0 if single else 1) + dictionary_len + content_size_len
        if at + header_len > size:
            raise CaptureError('truncated Zstandard header')
        try:
            parameters = zstd.get_frame_parameters(data[at:at + header_len])
        except zstd.ZstdError:
            raise CaptureError('invalid Zstandard header') from None
        if parameters.dict_id or parameters.window_size > MAX_WINDOW:
            raise CaptureError('unsupported dictionary or window')

        cursor = at + header_len
        while True:
            if cursor + 3 > size:
                raise CaptureError('truncated Zstandard block header')
            block = int.from_bytes(data[cursor:cursor + 3], 'little')
            cursor += 3
            kind = (block >> 1) & 3
            block_size = block >> 3
            if kind == 3:
                raise CaptureError('reserved Zstandard block type')
            cursor += 1 if kind == 1 else block_size
            if cursor > size:
                raise CaptureError('truncated Zstandard block')
            if block & 1:
                break
        if flag & 0x04:
            cursor += 4
            if cursor > size:
                raise CaptureError('truncated Zstandard checksum')
        at = cursor



def complete_frames(data):
    try:
        _complete_frames(data)
    except CaptureError:
        raise
    except Exception:
        raise CaptureError('invalid Zstandard framing') from None


def decode_chunks(chunks):
    blocks = []
    for text in chunks:
        try:
            blocks.append(base64.b64decode(text.encode('ascii'),
                                           validate=True))
        except (ValueError, UnicodeError, binascii.Error):
            raise CaptureError('invalid base64 chunk') from None
    return blocks


def decompress_zstd(data, remaining):
    """Return decompressed bytes, rejecting anything over the shared budget."""
    output = []
    used = 0
    reader = zstd.ZstdDecompressor(max_window_size=MAX_WINDOW).stream_reader(
        io.BytesIO(data), read_across_frames=True)
    try:
        while True:
            want = min(1024 * 1024, remaining - used + 1)
            chunk = reader.read(want)
            if not chunk:
                break
            used += len(chunk)
            if used > remaining:
                raise CaptureError('decompressed byte budget')
            output.append(chunk)
    except CaptureError:
        raise
    except (zstd.ZstdError, ValueError, EOFError, OSError):
        raise CaptureError('invalid Zstandard data') from None
    finally:
        try:
            reader.close()
        except Exception:
            pass
    return b''.join(output)


def capture_records(context, lookup):
    """Decode captures and return (valid_records, rejected_indices)."""
    # The parser's own field size limit is a safety net.  The protocol limit
    # applies to the parsed UTF-8 byte length, so keep the raw CSV limit above
    # the total decompressed budget to allow quoted/doubled-quote fields.
    csv.field_size_limit(MAX_DECOMPRESSED)

    records = []
    rejected = []
    decoded_total = 0
    remaining = MAX_DECOMPRESSED
    record_count = 0

    for capture_index, capture in enumerate(context['captures']):
        blocks = decode_chunks(capture['chunks'])
        decoded_total += sum(len(block) for block in blocks)
        if decoded_total > MAX_DECODED:
            raise CaptureError('decoded byte budget')
        payload = b''.join(blocks)
        del blocks

        if capture['encoding'] == 'zstd':
            complete_frames(payload)
            data = decompress_zstd(payload, remaining)
        else:
            if len(payload) > remaining:
                raise CaptureError('decompressed byte budget')
            data = payload
        remaining -= len(data)
        del payload

        try:
            text = data.decode('utf-8')
        except UnicodeError:
            raise CaptureError('invalid UTF-8') from None
        del data

        reader = csv.reader(io.StringIO(text, newline=''), strict=True)
        try:
            header = next(reader, None)
        except csv.Error:
            raise CaptureError('invalid CSV header') from None
        if header != list(COLUMNS):
            raise CaptureError('invalid CSV header')

        try:
            for ordinal, values in enumerate(reader):
                record_count += 1
                if record_count > MAX_RECORDS:
                    raise CaptureError('logical record budget')
                too_large = False
                for value in values:
                    if len(value.encode('utf-8')) > MAX_FIELD_BYTES:
                        too_large = True
                        break
                if too_large:
                    raise CaptureError('field byte budget')
                if len(values) != 14:
                    rejected.append([capture_index, ordinal])
                    continue
                try:
                    record = parse_record(values, context, lookup)
                except (ValueError, TypeError, KeyError, IndexError,
                        OverflowError):
                    rejected.append([capture_index, ordinal])
                    continue
                records.append(record)
        except csv.Error:
            raise CaptureError('invalid CSV syntax') from None

    return records, rejected


